import json
from html import escape


sources = json.load(open('source.json'))
answers = []


def paragraphs(*texts):
    return '\n'.join('<p>' + escape(t, quote=False) + '</p>' for t in texts)


def article(index, xml, reason, notes, removed=None, benefit=None):
    source = sources[index]
    result = {k: source[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    result.update(proposed_xml=xml, reason=reason, review_notes=notes, status='rewrite_draft')
    if removed:
        result.update(
            change_type='normative_reduction',
            reform_policy_id='editorial_direction_2026_10_19',
            removed_provisions=removed,
        )
    if benefit:
        result['benefit_review'] = benefit
    answers.append(result)


article(
    0,
    paragraphs(
        "La procédure de licenciement pour motif économique est irrégulière lorsque l'entreprise n'a pas mis en place le comité social et économique alors qu'elle y est tenue et qu'aucun procès-verbal de carence n'a été établi.",
        "L'employeur doit alors verser au salarié une indemnité d'au moins un mois de salaire brut. Cette indemnité s'ajoute aux indemnités de licenciement et de préavis auxquelles le salarié a droit.",
    ),
    "Seconde passe : maintien de la réécriture antérieure à droit constant après examen des deux conditions et de la sanction. Le comité obligatoire garantit la représentation collective lors du licenciement économique ; le procès-verbal de carence permet de distinguer l'échec régulier de l'élection de son omission. Supprimer cette sanction priverait ces garanties de leur réparation minimale. Aucune formalité répétée ni cotisation accessoire n'est créée par cet article et aucune coupe supplémentaire ne se justifie dans son champ.",
    "Les deux conditions demeurent cumulatives et les deux alinéas sont conservés. Le minimum d'un mois de salaire brut est une sanction distincte : ni le seuil d'un an ni le plafond de six mois de l'indemnité ordinaire ne le limitent. Le salarié conserve cette réparation dès lors que ses conditions sont réunies, y compris sous contrat unique. Le préavis individuel de quinze jours ne dispense pas des procédures collectives ni de la mise en place du CSE. La source ne comporte ni note d'application ni tableau.",
)

article(
    1,
    paragraphs(
        "Lorsque la décision de validation prévue à l'article L. 1233-57-2 ou la décision d'homologation prévue à l'article L. 1233-57-3 est annulée pour un motif autre que ceux mentionnés au dernier alinéa du présent article et au deuxième alinéa de l'article L. 1235-10, le salarié est réintégré dans l'entreprise si les parties y consentent. Il conserve ses avantages acquis.",
        "À défaut de réintégration, l'employeur doit verser au salarié une indemnité au moins égale aux salaires des six derniers mois. Cette indemnité s'ajoute à l'indemnité de licenciement prévue à l'article L. 1234-9.",
        "Lorsque la décision de validation prévue à l'article L. 1233-57-2 ou la décision d'homologation prévue à l'article L. 1233-57-3 est annulée pour insuffisance de motivation, l'autorité administrative prend une nouvelle décision suffisamment motivée dans un délai de quinze jours à compter de la notification du jugement à l'administration. L'employeur porte cette décision à la connaissance des salariés licenciés à la suite de la première décision, par tout moyen donnant une date certaine à cette information. Pour les informations à délivrer à compter de l'entrée en vigueur de la loi portant la présente réforme, aucune nouvelle transmission n'est exigée à un salarié auquel la même décision a déjà été communiquée avec date certaine, notamment par l'autorité administrative. Les éléments établissant cette communication peuvent être réutilisés sans attestation supplémentaire.",
        "Dès que l'autorité administrative a pris cette nouvelle décision, l'annulation de sa première décision pour le seul motif d'insuffisance de motivation n'affecte pas la validité du licenciement. Elle n'ouvre droit ni à la réintégration du salarié ni à une indemnité à la charge de l'employeur.",
    ),
    "Seconde passe avec réduction de fond : suppression de la seconde communication obligatoire de la même décision à un salarié déjà informé avec date certaine. Les preuves existantes peuvent être réutilisées ; aucune attestation n'est créée. La dispense est individuelle et ne supprime pas l'information des autres salariés. À droit constant, la réécriture distingue réintégration consentie, réparation minimale et régularisation de la seule motivation administrative. Le contrôle du plan et les réparations ne sont pas retirés : ils protègent des licenciements collectifs irréguliers.",
    "Quatre alinéas conservés : le renvoi du premier au dernier vise toujours la neutralisation de l'annulation pour seule insuffisance de motivation. L. 1235-10, deuxième alinéa, L. 1233-57-2 et L. 1233-57-3 ont été lus dans le corpus. Les quinze jours courent de la notification du jugement à l'administration ; ce délai de régularisation n'est pas le préavis individuel. Les six derniers mois constituent un minimum de réparation, non un plafond. La dispense ne vaut que si la même décision complète a effectivement été communiquée au salarié avec date certaine ; aucun nouveau fichier ou certificat n'est imposé. Elle vise les informations restant à délivrer après l'entrée en vigueur, sans effacer une omission déjà consommée ni les créances et recours antérieurs. Le minimum distinct de L. 1234-9 suit sa transition propre sans absorber la sanction.",
    removed=[
        "Obligation pour l'employeur de communiquer une seconde fois la même décision au salarié qui l'a déjà reçue avec date certaine.",
    ],
)

article(
    2,
    paragraphs(
        "Lorsque l'employeur prend l'initiative de rompre le contrat conclu pour une mission à l'exportation dans le champ de l'article L. 1223-5, la rupture relève des dispositions du chapitre II relatives au licenciement pour motif personnel.",
        "Pour les contrats conclus à compter de l'entrée en vigueur de la loi instituant le contrat de travail unique, l'emploi est à durée indéterminée. La fin de la mission à l'exportation ne rompt pas automatiquement le contrat. L'employeur qui entend le rompre respecte les règles de rupture applicables au contrat unique, le contrôle du motif et les garanties propres à la mission, notamment celles de l'article L. 1223-6. Le préavis individuel de quinze jours calendaires ne tient pas lieu des autorisations ou procédures distinctes légalement requises.",
        "Les contrats conclus avant cette entrée en vigueur conservent leur régime et leurs garanties antérieurs. Une conversion convenue en contrat unique conserve toute l'ancienneté et les créances acquises, sans compter deux fois une même période dans le calcul d'une même indemnité. Les indemnités spéciales et les garanties conventionnelles ou contractuelles plus favorables restent applicables dans leur champ.",
    ),
    "Seconde passe : coordination de fond avec le contrat unique, absente de la proposition antérieure. La dérogation favorable au régime du licenciement économique est conservée dans le champ de L. 1223-5 ; elle ne devient ni un CDD ni une fin automatique d'emploi. Aucune nouvelle coupe du chapitre II ne se justifie ici : le motif contrôlable, la défense du salarié et le recours restent nécessaires à cette rupture patronale. L'article ne comporte aucune autorisation de mission ou déclaration supplémentaire à supprimer.",
    "L. 1223-5 et L. 1223-6 ont été lus intégralement, source et proposition du corpus : la source du premier vise une mission accomplie en majeure partie hors du territoire national et la rupture patronale à la fin de la mission ; sa proposition supprime déjà le préalable systématique d'un accord collectif. Le présent article ne rétablit pas ce préalable et n'élargit pas de lui-même le champ de la dérogation. Le 3° de L. 1223-6 maintient une indemnité spéciale proratisée sans condition d'ancienneté : le seuil d'un an de l'indemnité ordinaire ne doit pas lui être importé. Coordonner explicitement ces deux articles avec l'absence de terme du contrat unique ; leurs propositions consultées ne suffisent pas à considérer cette coordination générale comme achevée. Les agents publics ne sont pas visés. Aucun renvoi nouveau inexistant ni date de promulgation n'est créé.",
)

article(
    3,
    paragraphs(
        "Lorsqu'un salarié conclut un nouveau contrat de travail après avoir rompu abusivement un précédent contrat, le nouvel employeur répond solidairement du dommage causé à l'employeur précédent dans le seul cas suivant :",
        "1° Il est établi que le nouvel employeur est intervenu dans la rupture abusive ;",
        "2° Abrogé ;",
        "3° Abrogé.",
        "La seule embauche du salarié ou la poursuite de son emploi, même en connaissance du contrat précédent, ne suffit pas à engager cette responsabilité. Le présent article ne fait pas obstacle à la réparation d'une faute distincte personnellement imputable au nouvel employeur selon les règles de droit commun.",
        "Ces dispositions s'appliquent aux faits générateurs de responsabilité survenus à compter de l'entrée en vigueur de la loi portant la présente réforme. Les créances de réparation nées de faits antérieurs, leur prescription et les recours correspondants restent régis par les dispositions antérieures. La responsabilité du salarié pour une rupture abusive demeure régie par l'article L. 1237-2. Une rupture régulièrement notifiée avec le préavis qui lui est applicable ne devient pas abusive du seul fait de l'embauche par un autre employeur.",
    ),
    "Réduction de fond après seconde passe : suppression des deux cas de solidarité fondés sur la seule connaissance d'un contrat antérieur au recrutement ou lors de la poursuite de l'emploi. Ils exposaient le nouvel employeur sans participation démontrée à l'abus et freinaient la mobilité professionnelle. Le 1° conserve la responsabilité pour intervention prouvée dans la rupture abusive ; les dommages, la responsabilité du salarié et les fautes personnelles distinctes restent réparables. Les subdivisions supprimées sont conservées comme abrogées. La référence au terme d'un nouveau CDD disparaît avec ces cas et ne réintroduit pas un emploi à durée déterminée.",
    "La condition préalable de rupture abusive, la preuve de l'intervention et le dommage à l'employeur précédent sont maintenus. Les anciennes dispenses du 3° (terme du CDD, expiration du préavis du CDI ou quinze jours écoulés au moment de l'avertissement) n'ont plus d'objet pour les faits nouveaux puisque le cas de responsabilité correspondant est supprimé en entier ; elles restent applicables aux faits antérieurs. Le délai de quinze jours de cette ancienne dispense était distinct du nouveau préavis individuel de quinze jours calendaires. L. 1237-2 a été lu et sa réparation autonome demeure. Le simple fait de changer d'employeur après un préavis régulier ne constitue pas un abus ; les règles de non-concurrence valables, de loyauté, de durée du travail et les fautes personnelles distinctes ne sont pas abrogées implicitement.",
    removed=[
        "Solidarité automatique du nouvel employeur ayant recruté en sachant que le salarié était encore lié par un autre contrat de travail, sans intervention prouvée dans l'abus.",
        "Solidarité du nouvel employeur pour la seule poursuite de l'emploi après connaissance du contrat précédent, ainsi que le mécanisme de délai et d'expiration exclusivement attaché à ce cas supprimé.",
    ],
)

article(
    4,
    paragraphs(
        "Le salarié qui quitte volontairement l'entreprise pour bénéficier d'une pension de vieillesse a droit à une indemnité de départ à la retraite.",
        "Le taux de cette indemnité dépend de l'ancienneté du salarié dans l'entreprise. Son calcul tient compte de la rémunération brute dont il bénéficiait auparavant. Le taux et les modalités de calcul sont fixés par voie réglementaire.",
        "Un salarié ne peut bénéficier que d'une seule indemnité de départ ou de mise à la retraite. Sous réserve du dernier alinéa, cette indemnité lui est attribuée lorsqu'il fait valoir ses droits à une pension de vieillesse de droit propre auprès du régime de base auquel il est affilié au titre de l'emploi qu'il occupe dans l'entreprise.",
        "L'indemnité de départ à la retraite peut être affectée au maintien total ou partiel de la rémunération du salarié en fin de carrière lorsque celui-ci, à sa demande et avec l'accord de son employeur, passe à temps partiel ou à temps réduit par rapport à la durée maximale légale ou conventionnelle de travail exprimée en jours. Un accord d'entreprise ou d'établissement ou, à défaut, une convention ou un accord de branche peut organiser cette affectation. À compter de l'entrée en vigueur de la loi portant la présente réforme, en l'absence d'un tel texte collectif, le salarié et l'employeur peuvent convenir directement de cette affectation dans les mêmes conditions. Si l'indemnité de départ qui aurait été due au moment où le salarié fait valoir ses droits à retraite dépasse les sommes affectées au maintien de sa rémunération, la différence lui est versée. Les affectations déjà convenues et les garanties conventionnelles ou contractuelles plus favorables demeurent applicables.",
    ),
    "Seconde passe avec réduction de fond : suppression de la nécessité d'un texte collectif préalable pour accéder à l'affectation favorable de l'indemnité au maintien de rémunération. L'accord direct du salarié et de l'employeur devient possible en son absence, sans nouvelle autorisation ni déclaration. Le consentement des deux parties, le passage demandé à temps réduit et le versement du reliquat protègent le salarié et sont conservés. Les trois premiers alinéas sont réécrits à droit constant ; l'indemnité spéciale de retraite n'est pas remplacée par l'indemnité ordinaire de rupture.",
    "Quatre alinéas conservés ; le renvoi au dernier alinéa demeure exact. D. 1237-1 et D. 1237-2 ont été lus : minima d'un demi-mois après dix ans, un mois après quinze ans, un mois et demi après vingt ans, deux mois après trente ans et salaire de référence le plus favorable entre douzième des douze derniers mois et tiers des trois derniers mois, avec primes proratisées. Aucun de ces paramètres n'est modifié ici. L'unicité, la pension de droit propre et le régime de base de l'emploi occupé sont maintenus. Le temps réduit en jours reste distinct du temps partiel. Ni le seuil d'un an, ni le taux de 0,20 mois, ni le plafond de six mois de l'indemnité ordinaire ne s'appliquent à cette indemnité spéciale. La nouvelle faculté vaut aussi pour les futurs salariés éligibles et ne modifie pas une affectation déjà convenue sans leur accord. L. 1237-7 et L. 1237-10 ont été lus : mise à la retraite et préavis de départ ont leurs règles propres. La réforme de capitalisation ne supprime pas ce droit.",
    removed=[
        "Condition d'existence d'un accord d'entreprise ou d'établissement ou, à défaut, d'un texte de branche pour convenir de l'affectation de l'indemnité au maintien de rémunération en fin de carrière.",
    ],
)

article(
    5,
    paragraphs(
        "Les salariés protégés mentionnés aux articles L. 2411-1 et L. 2411-2 peuvent recourir à la rupture conventionnelle prévue par la présente section. Par dérogation à l'article L. 1237-14, cette rupture doit être autorisée par l'inspecteur du travail dans les conditions prévues au chapitre Ier du titre Ier du livre IV, à la section 1 du chapitre Ier et au chapitre II du titre II du livre IV de la deuxième partie. Dans ce cas, par dérogation à l'article L. 1237-13, la rupture intervient à la date convenue par les parties, au plus tôt le jour de l'autorisation et après expiration du délai de rétractation. La suppression de l'attente jusqu'au lendemain s'applique aux conventions conclues à compter de l'entrée en vigueur de la loi portant la présente réforme ; les conventions antérieures conservent leur régime de date de rupture.",
        "Pour un médecin du travail, la rupture conventionnelle nécessite l'autorisation de l'inspecteur du travail. Celui-ci statue après avoir recueilli l'avis du médecin inspecteur du travail.",
    ),
    "Seconde passe avec réduction de fond ciblée : suppression, pour les conventions nouvelles visées au premier alinéa, du jour d'attente supplémentaire après autorisation. Le contrôle indépendant et le délai de rétractation accomplis rendent ce délai résiduel inutile ; la date convenue reste opposable. L'autorisation n'est pas supprimée : elle protège la représentation des salariés et l'indépendance du médecin du travail, conformément à la coordination travail. À droit constant, la rédaction précise les deux voies et conserve tous les renvois procéduraux.",
    "L. 2411-1, L. 2411-2 et L. 1237-11 à L. 1237-14 ont été lus dans le corpus. Les trois ensembles procéduraux du premier alinéa demeurent inchangés. L'autorisation demeure substituée à l'homologation ordinaire : pas de seconde homologation ni d'importation de son acceptation tacite. Les quinze jours calendaires de rétractation de L. 1237-13 ne sont pas le préavis individuel et restent entiers. La suppression du lendemain est explicite, contrairement à la proposition précédente ; elle n'accélère pas une convention antérieure et ne supprime pas une suspension juridictionnelle ou un obstacle autonome. Le deuxième alinéa conserve sans assimilation son autorisation et l'avis préalable médical. L. 1237-18-4 et L. 1237-19-2 ont été lus : leur lendemain d'autorisation relève d'autres ruptures et n'est pas abrogé par cet article. R. 4745-2 doit être coordonné pour ne sanctionner que les obligations subsistantes et les faits anciens selon le droit pénal applicable ; son renvoi ne peut rétablir le jour retiré dans le champ nouveau. Le minimum spécifique de L. 1237-13 conserve son champ et sa transition, sans seuil d'un an de l'indemnité ordinaire.",
    removed=[
        "Délai résiduel imposant d'attendre le lendemain du jour de l'autorisation avant la rupture conventionnelle nouvelle des salariés visés au premier alinéa, après rétractation et contrôle protecteur.",
    ],
    benefit="L'accès des salariés protégés de L. 2411-1 et L. 2411-2 à la rupture conventionnelle est maintenu pour les conventions futures. La dérogation à L. 1237-14 conserve une autorisation unique de l'inspecteur, sans ajouter une homologation. L'autorisation, l'avis médical préalable propre aux médecins du travail, la rétractation et l'indemnité spécifique de L. 1237-13 restent applicables dans leur champ. Seul le jour d'attente suivant l'autorisation est retiré pour les nouvelles conventions du premier alinéa, avec maintien de la date convenue ; aucune exonération fiscale ou sociale ni dispense favorable n'est supprimée.",
)

article(
    6,
    paragraphs(
        "L'accord collectif fixe :",
        "1° La durée du congé de mobilité ;",
        "2° Les conditions que le salarié doit remplir pour bénéficier de ce congé ;",
        "3° Les modalités selon lesquelles le salarié adhère à la proposition de l'employeur, y compris les conditions dans lesquelles il exprime son consentement écrit, ainsi que les engagements de chaque partie ;",
        "4° L'organisation des périodes de travail, les conditions dans lesquelles le congé prend fin et les modalités d'accompagnement des actions de formation envisagées. Pour les contrats de travail conclus à compter de l'entrée en vigueur de la loi instituant le contrat de travail unique, la durée d'une période de travail ou de formation ne fixe pas le terme de l'emploi, qui est à durée indéterminée. Les contrats antérieurs conservent leur régime et les droits correspondants. La rupture d'un commun accord du contrat ayant donné lieu au congé demeure régie par l'article L. 1237-18-4 ;",
        "5° Le niveau de la rémunération versée pendant le congé de mobilité ;",
        "6° Les conditions dans lesquelles les institutions représentatives du personnel sont informées. Pour les informations à délivrer à compter de l'entrée en vigueur de la loi portant la présente réforme, les mêmes informations déjà effectivement communiquées aux mêmes destinataires dans l'exercice de leurs attributions n'ont pas à leur être transmises de nouveau ; seuls les compléments et changements nécessaires sont communiqués ;",
        "7° Les indemnités de rupture garanties au salarié. Leur montant ne peut être inférieur à celui des indemnités légales dues en cas de licenciement pour motif économique. Le renvoi au barème de l'article L. 1234-9 pour fixer ce minimum ne soumet pas l'indemnité spécifique de départ d'un commun accord au seuil d'un an propre à l'indemnité ordinaire de rupture. Pour les contrats antérieurs à la loi instituant le contrat de travail unique, la composante correspondant à l'ancienneté acquise avant son entrée en vigueur conserve son régime et ses minima ; elle s'ajoute à la composante nouvelle selon les dispositions transitoires de cet article, sans double compte d'une même période. Les garanties conventionnelles ou contractuelles plus favorables et les indemnités déjà convenues sont préservées.",
    ),
    "Seconde passe : suppression de la répétition des informations déjà reçues par les mêmes représentants du personnel, sans protocole ni attestation de remplacement. Les sept thèmes restent nécessaires pour définir un congé volontaire, rémunéré et assorti d'un accompagnement effectif ; ni le consentement écrit ni le niveau de rémunération ni l'indemnité spécifique ne sont supprimés. La proposition antérieure est coordonnée avec le contrat unique et corrigée pour ne pas importer le nouveau seuil d'un an de l'indemnité ordinaire dans cette rupture amiable spéciale. La durée des activités du congé ne vaut pas durée de l'emploi nouvellement conclu.",
    "Les 1° à 7° sont maintenus à leur place. L. 1237-17 à L. 1237-18-5 ont été lus : le contrat support du congé est rompu d'un commun accord selon L. 1237-18-4, tandis qu'un emploi nouveau pendant le congé est à durée indéterminée selon la coordination de L. 1237-18-1. Leur distinction évite un terme de CDD réintroduit par la formation. Le 6° ne dispense jamais d'un élément nouveau ni de l'information effective de chaque destinataire. Au 7°, coordonner L. 1234-9 et R. 1234-1, R. 1234-2 et R. 1234-4 : barème nouveau de 0,20 mois par année totale, prorata, plafond du seul montant légal de référence, part d'ancienneté antérieure protégée et salaire de référence propre. Le seuil d'un an, apprécié préavis inclus pour une rupture ordinaire, ne devient pas une franchise de cette indemnité spéciale. Les garanties des accords déjà conclus ne sont pas diminuées. L. 1237-18-3 conserve rémunération minimale et régime social favorable pendant douze mois, porté à vingt-quatre mois en cas de reconversion, y compris pour les futurs bénéficiaires éligibles. La note source relative au X de l'article 40 et au III de l'article 10 de l'ordonnance 2017-1387 fixe seulement l'entrée en vigueur historique des mesures d'application au plus tard le 1er janvier 2018 ; elle n'est pas une date de la réforme proposée.",
    removed=[
        "Seconde transmission obligatoire aux mêmes représentants du personnel d'informations identiques sur le congé de mobilité qui leur ont déjà été effectivement communiquées dans leurs attributions.",
    ],
)

article(
    7,
    paragraphs(
        "L'accord portant rupture conventionnelle collective fixe :",
        "1° Les modalités et les conditions dans lesquelles le comité social et économique est informé, s'il existe ;",
        "2° Le nombre maximal de départs envisagés et de suppressions d'emplois associées, ainsi que la durée pendant laquelle des ruptures de contrat de travail peuvent être engagées sur le fondement de cet accord ;",
        "3° Les conditions que le salarié doit remplir pour bénéficier du dispositif ;",
        "4° Les modalités de présentation et d'examen des candidatures des salariés au départ. Pour les conventions individuelles conclues à compter de l'entrée en vigueur de la loi portant la présente réforme, le consentement écrit du salarié au dispositif est exprimé dans la convention individuelle de rupture mentionnée au 4° bis ou, le cas échéant, au 4° ter, sans transmission préalable d'un accord écrit distinct. La candidature seule ne vaut pas consentement à la rupture ;",
        "4° bis Les modalités selon lesquelles l'employeur et le salarié concluent une convention individuelle de rupture et les parties exercent leur droit de rétractation ;",
        "4° ter Le cas échéant, les modalités selon lesquelles l'employeur et le salarié concluent une convention individuelle de rupture dans le cadre de la période de reconversion mentionnée à l'article L. 6324-1 ;",
        "5° Les modalités de calcul des indemnités de rupture garanties au salarié. Leur montant ne peut être inférieur à celui des indemnités légales dues en cas de licenciement. Le renvoi au barème de l'article L. 1234-9 pour fixer ce minimum ne soumet pas l'indemnité spécifique de rupture conventionnelle collective au seuil d'un an propre à l'indemnité ordinaire de rupture. Pour les contrats antérieurs à la loi instituant le contrat de travail unique, la composante correspondant à l'ancienneté acquise avant son entrée en vigueur conserve son régime et ses minima ; elle s'ajoute à la composante nouvelle selon les dispositions transitoires de cet article, sans double compte d'une même période. Les indemnités déjà garanties par un accord ou une convention individuelle et les garanties plus favorables ne sont pas diminuées ;",
        "6° Les critères permettant de départager les candidats potentiels au départ ;",
        "7° Les mesures destinées à faciliter l'accompagnement et le reclassement externe des salariés sur des emplois équivalents. Ces mesures peuvent notamment prendre la forme d'un congé de mobilité dans les conditions prévues aux articles L. 1237-18-1 à L. 1237-18-5, d'actions de formation, de validation des acquis de l'expérience ou de reconversion, ou d'actions soutenant la création d'activités nouvelles ou la reprise d'activités existantes par les salariés ;",
        "7° bis Le cas échéant, les mesures mentionnées au II de l'article L. 6324-9 ;",
        "8° Les modalités de suivi de la mise en œuvre effective de l'accord portant rupture conventionnelle collective.",
        "En application du X de l'article 40 et du III de l'article 10 de l'ordonnance n° 2017-1387 du 22 septembre 2017, les dispositions issues de l'article 10 de cette ordonnance qui nécessitent des mesures d'application entrent en vigueur à la date de publication des décrets d'application et, au plus tard, le 1er janvier 2018.",
    ),
    "Seconde passe avec réduction de fond au 4° : suppression de l'accord écrit préalable distinct à transmettre pour adhérer au dispositif, le consentement figurant dans la convention individuelle déjà exigée. L'examen des candidatures, les critères de départage, la signature volontaire et la rétractation restent nécessaires et sont conservés. Les autres clauses sont réécrites intégralement, avec correction du renvoi indemnitaire pour maintenir l'indemnité spécifique sans importer le seuil d'un an de l'indemnité ordinaire. La validation administrative, les mesures concrètes de reclassement et le suivi collectif ne sont pas supprimés par le préavis individuel du contrat unique.",
    "Ordre et numéros conservés, notamment 4° bis, 4° ter, 7° et 7° bis. Les renvois au 7° de L. 1237-19-3 et D. 1237-12 gardent leur cible. L. 1237-19 à L. 1237-19-5, L. 1237-19-7, L. 1237-19-8, D. 1237-9 et D. 1237-12 ont été lus : leur validation, contrôle de l'information du CSE, bilan et recours demeurent ; ils ne doivent pas exiger de nouveau l'écrit d'adhésion distinct supprimé. Le consentement doit rester effectif et libre ; une candidature ou un silence n'y suffit pas. Au 5°, le barème de référence de L. 1234-9 est coordonné avec 0,20 mois par année, prorata et plafond légal, sans plafond global des garanties négociées ni remise à zéro de l'ancienneté antérieure. L. 6324-1 et le II de L. 6324-9 ont été lus : qualification, reconversion, maintien de rémunération, frais pédagogiques et consentement à la mobilisation du CPF restent à leur champ. La durée d'une convention de départ ou d'une formation ne fixe pas un terme à l'emploi nouveau. La note d'entrée en vigueur du II de l'article 11 de la loi 2025-989 fixe le 1er janvier 2026 pour sa propre rédaction ; les actions engagées sous l'ancien régime gardent la transition du III constatée dans L. 6324-1 et L. 6324-9. L'alinéa final relatif à 2017 figure dans source_xml et reste à sa place ; ses dates, comme la note de 2026, ne sont pas utilisées pour dater la présente réforme.",
    removed=[
        "Transmission d'un accord écrit d'adhésion au dispositif distinct de la convention individuelle de rupture qui exprime déjà le consentement écrit du salarié, pour les conventions individuelles nouvelles.",
    ],
)

article(
    8,
    paragraphs(
        "Les entreprises de travail temporaire peuvent, par dérogation au principe d'exclusivité prévu à l'article L. 1251-2, exercer les activités suivantes :",
        "1° Les activités de placement privé prévues à l'article L. 5321-1 ;",
        "2° L'activité d'entreprise de travail à temps partagé.",
    ),
    "Seconde passe : maintien de la proposition antérieure à droit constant après examen de chaque disposition. L'article ne crée que deux dérogations favorables à l'exclusivité et aucune formalité, taxe ou autorisation propre ; les supprimer restreindrait les activités permises. Leur maintien n'est pas réservé aux entreprises déjà en activité. L'exclusivité générale relève de L. 1251-2 et ne peut être supprimée silencieusement à travers cet article favorable.",
    "Les trois alinéas et les 1° et 2° sont conservés. L. 1251-2, L. 5321-1 et L. 1252-1, L. 1252-2, L. 1252-4 ont été lus : le placement rapproche offres et demandes sans faire du placeur une partie au contrat de travail ; le temps partagé constitue une activité distincte, avec un emploi réputé à durée indéterminée. La dérogation ne permet aucun nouveau CDD et ne supprime ni la garantie de rémunération ni les droits d'intermission applicables à l'emploi intérimaire. Aucune pièce justificative supplémentaire n'est ajoutée. La présente conservation n'atteste pas une réécriture de l'exclusivité générale ou des autres régimes.",
    benefit="Les deux avantages sont la faculté d'exercer le placement privé de L. 5321-1 et celle d'exercer l'activité de travail à temps partagé malgré l'exclusivité de L. 1251-2. Les 1° et 2° les conservent intégralement, pour les entreprises et activités futures comme pour celles déjà existantes, sans agrément, déclaration ou condition supplémentaire. Leurs régimes propres et les garanties des salariés ne sont pas supprimés ; aucune exonération fiscale ou sociale n'est retirée.",
)

article(
    9,
    paragraphs(
        "Quel que soit son motif, une mission ne peut avoir pour objet de pourvoir durablement un emploi lié à l'activité normale et permanente de l'entreprise utilisatrice. Elle ne peut pas davantage produire cet effet.",
        "Cette interdiction porte sur l'affectation auprès de l'entreprise utilisatrice, y compris lorsqu'elle est constatée par une lettre de mission. Elle ne limite pas la durée de l'emploi auprès de l'entreprise de travail temporaire : pour les contrats conclus à compter de l'entrée en vigueur de la loi instituant le contrat de travail unique, cet emploi est à durée indéterminée. La fin de la mission ne rompt pas le contrat et ne fait pas perdre les garanties de rémunération, de congés et d'ancienneté des périodes sans mission prévues aux articles L. 1251-58-2 et L. 1251-58-3.",
        "Les contrats de mission conclus avant cette entrée en vigueur conservent leurs règles antérieures de durée et les droits correspondants jusqu'à leur terme, sans nouveau contrat ou renouvellement à durée déterminée après cette date. Une conversion convenue conserve l'ancienneté et les créances acquises.",
    ),
    "Seconde passe : coordination de fond de l'interdiction avec l'emploi intérimaire unique à durée indéterminée, sans coupe supplémentaire de la règle contre le pourvoi durable d'un emploi permanent chez l'utilisateur. Cette règle vise l'affectation et non la durée du contrat avec l'agence ; elle empêche le détournement de l'intérim et conserve le recours du salarié contre l'utilisateur. Sa suppression confondrait emploi durable auprès de l'agence et mise à disposition permanente. Le texte ne comporte ni formalité ni délai minimal autonome à retirer.",
    "L'alternative objet ou effet, l'indifférence du motif et les critères d'activité normale et permanente sont maintenus. L. 1251-1, L. 1251-6, L. 1251-12, L. 1251-40 et L. 1251-58-1 à L. 1251-58-6 ont été lus. L. 1251-58-5 remplace déjà contrat de mission par lettre de mission ; le premier alinéa vise directement l'affectation sans contourner cette substitution. L. 1251-40 conserve les droits à l'égard de l'utilisateur en cas de recours illicite, même si l'emploi auprès de l'agence est déjà à durée indéterminée ; cette articulation doit être expressément coordonnée dans cet autre article, sans le considérer réécrit ici. La dispense de durée totale de L. 1251-58-6 est maintenue, mais ne devient pas une dispense de la présente interdiction. Le caractère temporaire de la mise à disposition et la prévention des abus appellent aussi la confrontation avec la directive 2008/104/CE ; aucun texte européen n'a été retiré ni sa compatibilité réputée acquise. Le régime des utilisateurs publics reste distinct.",
)

article(
    10,
    '\n'.join([
        paragraphs("En plus des cas prévus à l'article L. 1251-6, un salarié peut être mis à la disposition d'une entreprise utilisatrice dans les cas suivants :"),
        '<div>' + paragraphs("1° Lorsque la mission vise à favoriser le recrutement de personnes sans emploi rencontrant des difficultés sociales et professionnelles particulières. Le recours à ce cas ne nécessite pas une habilitation par une disposition légale spéciale ou un accord de branche étendu ;") + '</div>',
        '<div>' + paragraphs("2° Lorsque l'entreprise de travail temporaire et l'entreprise utilisatrice s'engagent à assurer au salarié un complément de formation professionnelle, pour une durée et dans des conditions fixées par décret ou par accord de branche étendu ;") + '</div>',
        paragraphs("3° Lorsque l'entreprise de travail temporaire et l'entreprise utilisatrice s'engagent à assurer au salarié une formation professionnelle par la voie de l'apprentissage. Cette formation vise l'obtention d'une qualification professionnelle sanctionnée par un diplôme ou un titre à finalité professionnelle enregistré au répertoire national des certifications professionnelles. Elle est dispensée pour partie dans l'entreprise utilisatrice et pour partie en centre de formation d'apprentis ou section d'apprentissage, en application de l'article L. 6221-1 ;"),
        '<p>' + escape("4° Lorsque le salarié est l'une des personnes mentionnées à l'article L. 5212-13, à l'exclusion de celles mentionnées au 5° de cet article ;", quote=False) + '<br /><br />' + escape("5° Lorsque la mise à disposition est réalisée en application de l'article L. 5132-6, sans durée minimale légale d'un mois pour cette mission.", quote=False) + '</p>',
        paragraphs(
            "Les suppressions de l'habilitation préalable du 1° et de la durée minimale du 5° s'appliquent aux mises à disposition convenues à compter de l'entrée en vigueur de la loi portant la présente réforme. Les missions déjà convenues conservent leurs engagements et les droits acquis des salariés ; leur durée n'est pas réduite unilatéralement du fait de cette réforme.",
            "Pour les embauches à compter de l'entrée en vigueur de la loi instituant le contrat de travail unique, le salarié est lié à l'entreprise de travail temporaire par un contrat unique à durée indéterminée. La mission, la formation, l'apprentissage ou le parcours d'insertion peut avoir une durée limitée sans mettre fin à cet emploi. La rémunération mensuelle garantie et les droits des périodes sans mission demeurent applicables selon les articles L. 1251-58-2 et L. 1251-58-3. Les contrats antérieurs et leurs créances sont préservés ; aucun nouveau contrat de mission à durée déterminée ni renouvellement à durée déterminée ne peut être conclu après cette entrée en vigueur.",
            "Les aides, exonérations, droits à la formation, droits sociaux et d'accès au logement ainsi que les autres avantages attachés aux publics et aux actions visés au présent article restent ouverts aux futures situations éligibles réalisées sous contrat unique, selon leurs autres conditions propres, sans exiger la conclusion d'un contrat de travail à durée déterminée. La suppression de l'habilitation du 1° ne supprime ni les engagements d'insertion ni les garanties conventionnelles plus favorables applicables.",
        ),
    ]),
    "Seconde passe avec deux réductions concrètes : retrait de l'habilitation légale spéciale ou conventionnelle préalable pour le recrutement d'insertion du 1°, et suppression du minimum d'un mois de mission au 5°. Ces restrictions ne sont pas nécessaires à la formation ni au contrôle de l'éligibilité des publics. Les cinq voies favorables de mise à disposition, le complément de formation, l'apprentissage qualifiant et leur cadre pédagogique sont intégralement maintenus. La référence au contrat de mission limité est coordonnée avec le contrat unique : le terme de l'affectation ne termine plus l'emploi. Les aides et exonérations restent accessibles pour les situations futures éligibles.",
    "Subdivisions 1° à 5°, conteneurs des 1° et 2° et regroupement des 4° et 5° sont conservés. Le retrait du minimum d'un mois est spécifique à la mission d'insertion : il n'est pas la suppression du plancher hebdomadaire de vingt-quatre heures. L. 5132-6 a été lu : son exclusion actuelle de la section 4 bis et ses renvois aux contrats de mission, au renouvellement, au CDD de deux mois et à L. 3123-6 doivent être expressément coordonnés pour ouvrir l'emploi intérimaire d'insertion au contrat unique et conserver les dispenses de carence et autres avantages pour les futures situations ; ce travail hors du lot n'est pas déclaré achevé. L. 1251-6, L. 1251-40 et le 12° de L. 2253-1 ont été lus : coordonner le pouvoir de branche pour qu'il n'impose pas à nouveau l'habilitation préalable supprimée, sans retirer les garanties négociées autonomes. Le décret ou l'accord étendu du 2° règle toujours la formation, sans fixer un terme à l'emploi. L. 6221-1 et L. 5212-13 ont été lus : RNCP, deux lieux de formation et exclusion du seul 5° de L. 5212-13 restent exacts. Les règles d'apprentissage et de financement hors de cet article doivent également être coordonnées avec le contrat unique. Aucun agrément, formulaire, prélèvement de remplacement ni reconduction de CDD n'est créé.",
    removed=[
        "Habilitation préalable par une disposition légale spéciale ou un accord de branche étendu pour une mission visant l'insertion des personnes sans emploi en difficultés sociales et professionnelles particulières.",
        "Durée minimale légale d'un mois de la mission d'insertion visée au 5°, sans réduire les périodes de travail ni les rémunérations déjà garanties par les engagements antérieurs.",
    ],
    benefit="Les cinq possibilités favorables de recours subsistent : recrutement d'insertion du 1°, complément de formation du 2°, apprentissage qualifiant du 3°, publics de L. 5212-13 avec la même exclusion au 4°, insertion de L. 5132-6 au 5°. Les deux coupes élargissent l'accès sans retirer formation, diplôme ou titre RNCP, rémunération, accompagnement ou garanties négociées. Les aides, exonérations et droits sociaux restent ouverts aux futures situations éligibles sous contrat unique ; aucune condition de CDD n'est conservée pour les en priver. La durée des missions ou des phases pédagogiques ne termine pas l'emploi et les garanties d'intermission sont maintenues. L'exclusion de la section 4 bis dans L. 5132-6 est identifiée comme coordination indispensable, non réputée déjà supprimée dans le corpus.",
)

article(
    11,
    paragraphs(
        "Un licenciement pour motif économique ne fait pas obstacle, à lui seul, au recours à un salarié d'une entreprise de travail temporaire pour répondre à un accroissement temporaire de l'activité, y compris pour exécuter une tâche occasionnelle, précisément définie et non durable, ne relevant pas de l'activité normale de l'entreprise utilisatrice. Aucun délai d'attente de six mois n'est imposé sur ce fondement.",
        "Cette règle s'applique aussi aux postes concernés par le licenciement dans l'établissement. Les autres conditions de recours au travail temporaire, notamment celles des articles L. 1251-5 à L. 1251-7 et L. 1251-10, demeurent applicables.",
        "La possibilité de recourir au travail temporaire après un licenciement économique n'est plus subordonnée à la brièveté ou au non-renouvellement de la mission ni à une commande exceptionnelle à l'exportation. L'information et la consultation préalables du comité social et économique exigées sur le seul fondement de l'ancien 2° ne sont plus requises. Les obligations d'information et de consultation ayant un fondement légal autonome demeurent applicables.",
        "1° Abrogé ;",
        "2° Abrogé.",
        "L'employeur qui a procédé au licenciement économique reste tenu de respecter la priorité de réembauche prévue à l'article L. 1233-45.",
        "La suppression de l'interdiction et de ses conditions dérogatoires s'applique aux mises à disposition convenues à compter de l'entrée en vigueur de la loi portant la présente réforme. Les contrats et engagements antérieurs ainsi que les droits acquis et recours correspondants conservent leur régime, sous réserve de l'application de la loi répressive plus douce aux sanctions non définitives et des règles applicables à l'exécution des condamnations. Aucune sanction ne peut être fondée sur l'interdiction supprimée pour les faits nouveaux.",
        "Cette liberté de recours concerne l'affectation temporaire auprès de l'utilisateur. Les salariés recrutés à compter de l'entrée en vigueur de la loi instituant le contrat de travail unique sont employés à durée indéterminée par l'entreprise de travail temporaire. La fin de la mission ne rompt pas cet emploi ; la rémunération garantie et les droits des périodes sans mission restent applicables. Aucun nouveau CDD ou renouvellement à durée déterminée n'est autorisé par le présent article.",
    ),
    "Seconde passe avec suppression de fond de l'interdiction de six mois après licenciement économique. La reprise d'activité peut être satisfaite sans attendre ni remplir les anciennes exceptions de trois mois non renouvelables ou de commande exceptionnelle à l'exportation. L'information-consultation préalable propre à cette dernière dérogation disparaît avec son support, sans déclaration de remplacement. La priorité de réembauche, les procédures collectives autonomes, la prévention des abus et la protection contre les travaux dangereux demeurent : elles protègent les salariés sans imposer ce gel général de recrutement. Les deux dérogations ne sont plus nécessaires puisque leur interdiction de base est supprimée.",
    "Les 1° et 2° restent repérables comme abrogés. L. 1233-45 a été lu en entier : priorité d'un an à compter de la rupture si le salarié la demande pendant ce délai, postes compatibles, nouvelle qualification signalée et information des représentants du personnel demeurent. L. 1251-10 a été lu : supprimer son seul renvoi introductif à l'ancienne interdiction, conserver interdiction de remplacement de grévistes, travaux dangereux et leur dérogation favorable, et remplacement d'un médecin du travail. L. 1251-58-5 doit conserver sa coordination de lettre de mission sans rétablir le gel. L. 1255-5 a été lu : retirer le renvoi répressif à l'ancienne interdiction pour les faits nouveaux, en maintenant les sanctions de L. 1251-10 (3 750 euros ; récidive six mois et 7 500 euros) dans leur champ. Les articles 112-1 et 112-4 du code pénal, hors du corpus assigné, constituent la coordination temporelle à traiter pour la loi plus douce et la cessation d'exécution des condamnations lorsque les faits perdent leur caractère d'infraction ; ces articles n'ont pas été réécrits ici. Le recours au salarié intérimaire ne dispense pas l'ancien employeur de proposer les emplois effectivement disponibles dans le champ de L. 1233-45. Les conditions d'affectation temporaire et garanties du contrat unique sont conservées ; aucune disparition implicite d'une contrainte européenne n'est affirmée.",
    removed=[
        "Interdiction de recourir au travail temporaire pendant six mois après un licenciement économique pour un accroissement temporaire d'activité sur les postes concernés dans l'établissement.",
        "Condition dérogatoire imposant une mission de trois mois au plus sans possibilité de renouvellement pour échapper à l'interdiction supprimée.",
        "Condition dérogatoire d'une commande exceptionnelle à l'exportation exigeant des moyens exorbitants et information-consultation préalable du CSE sur ce seul fondement.",
    ],
    benefit="Les dérogations de mission non renouvelable de trois mois au plus et de commande exceptionnelle à l'exportation allégeaient uniquement le gel de six mois. Ce gel est supprimé entièrement pour les mises à disposition nouvelles : leurs anciens bénéficiaires peuvent toujours recruter dans les mêmes cas, et plus largement, sans la restriction générale ni ses conditions d'exception. Aucune interdiction équivalente n'est créée. Les anciens contrats et leurs droits restent préservés. La priorité de réembauche demeure pour les salariés licenciés, ainsi que les garanties de rémunération et d'intermission sous contrat unique. L'article ne supprime aucun avantage fiscal, social ou de formation ni la dérogation autonome pour travaux dangereux de L. 1251-10.",
)


